CREATE INDEX "Goal_teamId_idx" ON "Goal"("teamId");
CREATE INDEX "Goal_categoryId_idx" ON "Goal"("categoryId");
CREATE INDEX "Goal_status_idx" ON "Goal"("status");
CREATE INDEX "GoalMember_userId_idx" ON "GoalMember"("userId");
CREATE UNIQUE INDEX "GoalMember_goalId_userId_key" ON "GoalMember"("goalId", "userId");
CREATE INDEX "GoalStep_goalId_idx" ON "GoalStep"("goalId");
CREATE UNIQUE INDEX "GoalStep_goalId_position_key" ON "GoalStep"("goalId", "position");
CREATE INDEX "GoalStepProgress_userId_idx" ON "GoalStepProgress"("userId");
CREATE UNIQUE INDEX "GoalStepProgress_goalStepId_userId_key" ON "GoalStepProgress"("goalStepId", "userId");
CREATE INDEX "Team_ownerUserId_idx" ON "Team"("ownerUserId");
CREATE INDEX "TeamMember_userId_idx" ON "TeamMember"("userId");
CREATE UNIQUE INDEX "TeamMember_teamId_userId_key" ON "TeamMember"("teamId", "userId");
CREATE UNIQUE INDEX "InviteLink_tokenHash_key" ON "InviteLink"("tokenHash");
CREATE INDEX "InviteLink_teamId_idx" ON "InviteLink"("teamId");
CREATE INDEX "InviteLink_goalId_idx" ON "InviteLink"("goalId");
CREATE INDEX "InviteLink_expiresAt_idx" ON "InviteLink"("expiresAt");
CREATE INDEX "InviteRedemption_userId_idx" ON "InviteRedemption"("userId");
CREATE UNIQUE INDEX "InviteRedemption_inviteLinkId_userId_key" ON "InviteRedemption"("inviteLinkId", "userId");
CREATE UNIQUE INDEX "Plan_code_key" ON "Plan"("code");
CREATE INDEX "Subscription_userId_idx" ON "Subscription"("userId");
CREATE INDEX "Subscription_planId_idx" ON "Subscription"("planId");

PRAGMA foreign_keys=ON;
